function [xopt, fopt, k] = gold618(fun, a, b, tol, maxit)

r = (sqrt(5) - 1) / 2;

x1 = b - r*(b-a);
x2 = a + r*(b-a);
f1 = fun(x1);
f2 = fun(x2);

k = 0;
while (b-a > tol) && (k < maxit)
    if f1 > f2
        a = x1;
        x1 = x2;
        f1 = f2;
        x2 = a + r*(b-a);
        f2 = fun(x2);
    else
        b = x2;
        x2 = x1;
        f2 = f1;
        x1 = b - r*(b-a);
        f1 = fun(x1);
    end
    k = k + 1;
end

xopt = (a+b)/2;
fopt = fun(xopt);

end

