function C = localClusteringCoeff(B)

n = size(B,1);
C = zeros(n,1);

for i = 1:n

    neigh = find(B(i,:) > 0);
    k = length(neigh);

    if k >= 2
        subB = B(neigh,neigh);
        actualEdges = nnz(triu(subB,1));

        C(i) = 2*actualEdges/(k*(k-1));
    else
        C(i) = 0;
    end

end

end

