function E = couponSim(p,N)

cnt = zeros(N,1);

for i = 1:N
    have = zeros(1,4);
    k = 0;

    while sum(have) < 4
        u = rand;
        cp = cumsum(p);
        card = find(u <= cp,1);

        have(card) = 1;
        k = k + 1;
    end

    cnt(i) = k;
end

E = mean(cnt);

end

